// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Unit tests for the manual single-step run
// Flo: build Sche without threads (stop on) > manuRun / abort > assert queue, ring, codes
// I/O: Task specs + step ids > ManuRes codes, queued Jobz, rings
// ===================================================================
const std = @import("std"); const stor = @import("taskstore"); const tick = @import("tk-task-tick.zig"); const conf = @import("store");
const tszz = std.testing; const Sche = tick.Sche;
fn initz(sche: *Sche, list: []stor.Task) !void { sche.gpaz = tszz.allocator; sche.root = try tszz.allocator.dupe(u8, "E:\\hub"); sche.stop.store(true, .release); sche.load = .{ .aren = std.heap.ArenaAllocator.init(tszz.allocator), .task = list, .reje = &.{}, .rawz_okay = true }; }
fn drain(sche: *Sche, iozz: std.Io) void { var wait: u32 = 0; while (sche.workBusy(iozz) and wait < 2000) : (wait += 10) std.Io.sleep(iozz, .fromMilliseconds(10), .awake) catch {}; }
fn tasks() [3]stor.Task { return .{ .{ .id = "real", .type = "hand", .run = "echo x", .tmo = 10 }, .{ .id = "solo", .type = "hand", .run = "echo y" }, .{ .id = "ch", .type = "boot", .sche = "boot", .tmo = 300, .@"try" = 2, .ids = &.{ "virt", "real", "scra-x", "s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8", "s9" } } }; }
test "manuRun: a virtual step is queued alone with the chain's settings, a ring and no retry" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); const resu = sche.manuRun(iozz, "virt", "once-aday"); try tszz.expectEqual(Sche.ManuCode.okzz, resu.code); try tszz.expect(!resu.wait); try tszz.expectEqual(@as(usize, 1), sche.queu.items.len); const jobz = sche.queu.items[0]; try tszz.expect(jobz.manu); try tszz.expect(!jobz.chai); try tszz.expectEqualStrings("virt", jobz.iden); try tszz.expect(std.mem.endsWith(u8, jobz.runz, " virt")); try tszz.expect(std.mem.indexOf(u8, jobz.runz, "hub") != null); try tszz.expectEqual(@as(u32, 0), jobz.retr); try tszz.expectEqual(@as(u32, 300_000), jobz.time_msec); try tszz.expect(jobz.teez != null); const ring = sche.manuRing(iozz, "virt").?; defer ring.rele(); try tszz.expectEqualStrings("once-aday", ring.tabz); try tszz.expect(!ring.doneChec(iozz)); var outz: std.Io.Writer.Allocating = .init(tszz.allocator); defer outz.deinit(); try outz.writer.writeAll("["); try sche.manuJobzWrit(iozz, &outz.writer, false); try tszz.expect(std.mem.indexOf(u8, outz.written(), "\"id\":\"virt\"") != null); try tszz.expect(std.mem.indexOf(u8, outz.written(), "\"tab\":\"once-aday\"") != null); try tszz.expect(std.mem.indexOf(u8, outz.written(), "\"manu\":true") != null); }
test "manuRun: a real task member keeps its own run and timeout; a task outside any chain runs too" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "real", "t").code); try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "solo", "t").code); try tszz.expectEqual(@as(usize, 2), sche.queu.items.len); try tszz.expectEqualStrings("echo x", sche.queu.items[0].runz); try tszz.expectEqual(@as(u32, 10_000), sche.queu.items[0].time_msec); try tszz.expectEqualStrings("echo y", sche.queu.items[1].runz); }
test "manuRun: bad id, unknown id and a chain id are refused, nothing is queued or leaked" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); try tszz.expectEqual(Sche.ManuCode.unknown, sche.manuRun(iozz, "a b", "t").code); try tszz.expectEqual(Sche.ManuCode.unknown, sche.manuRun(iozz, "x&calc", "t").code); try tszz.expectEqual(Sche.ManuCode.bad_id, sche.manuRun(iozz, "a/b", "t").code); try tszz.expectEqual(Sche.ManuCode.bad_id, sche.manuRun(iozz, "", "t").code); try tszz.expectEqual(Sche.ManuCode.unknown, sche.manuRun(iozz, "nope", "t").code); try tszz.expectEqual(Sche.ManuCode.is_chain, sche.manuRun(iozz, "ch", "t").code); try tszz.expectEqual(@as(usize, 0), sche.queu.items.len); try tszz.expect(sche.manuRing(iozz, "nope") == null); }
test "manuRun: refused while a chain that owns the step is running, allowed once it is idle" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); sche.chai[0] = .{ .used = true, .runn = true }; sche.chai[0].iden_leng = Sche.intoDupe(&sche.chai[0].iden_buff, "ch").len; const resu = sche.manuRun(iozz, "virt", "t"); try tszz.expectEqual(Sche.ManuCode.chain_run, resu.code); try tszz.expectEqualStrings("ch", resu.chaiName()); try tszz.expectEqual(@as(usize, 0), sche.queu.items.len); sche.chai[0].runn = false; try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "virt", "t").code); }
test "manuRun: a step already queued or running is busy, the failed try leaks nothing" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "virt", "t").code); try tszz.expectEqual(Sche.ManuCode.busy, sche.manuRun(iozz, "virt", "t").code); try tszz.expectEqual(@as(usize, 1), sche.queu.items.len); sche.jobzFree(sche.queu.orderedRemove(0)); sche.runn[0] = .{ .acti = true }; sche.runn[0].iden_leng = Sche.intoDupe(&sche.runn[0].iden_buff, "virt").len; try tszz.expectEqual(Sche.ManuCode.busy, sche.manuRun(iozz, "virt", "t").code); }
test "manuRun: a held lock is reported and noted in the ring, the job still queues" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); _ = conf.confApply(aren.allocator(), "{\"lock_list\":{\"scra\":[\"scra-\"]}}"); defer _ = conf.confApply(aren.allocator(), "{}"); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); sche.runn[0] = .{ .acti = true }; sche.runn[0].iden_leng = Sche.intoDupe(&sche.runn[0].iden_buff, "scra-other").len; sche.runn[0].lock_leng = Sche.intoDupe(&sche.runn[0].lock_buff, "scra").len; const resu = sche.manuRun(iozz, "scra-x", "t"); try tszz.expectEqual(Sche.ManuCode.okzz, resu.code); try tszz.expect(resu.wait); try tszz.expectEqualStrings("scra", resu.lockName()); try tszz.expectEqual(@as(usize, 1), sche.queu.items.len); const ring = sche.manuRing(iozz, "scra-x").?; defer ring.rele(); try tszz.expect(ring.size(iozz) > 0); }
test "manuAbor: pulls a queued manual job, seals its ring, and answers false when nothing is queued" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); try tszz.expect(!sche.manuAbor(iozz, "virt")); try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "virt", "t").code); try tszz.expect(sche.manuAbor(iozz, "virt")); try tszz.expectEqual(@as(usize, 0), sche.queu.items.len); const ring = sche.manuRing(iozz, "virt").?; defer ring.rele(); try tszz.expect(ring.doneChec(iozz)); try tszz.expect(!sche.manuAbor(iozz, "virt")); }
test "manu slots: a rerun replaces the step's ring, the ninth distinct step evicts the oldest" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "virt", "t").code); const first = sche.manuRing(iozz, "virt").?; defer first.rele(); try tszz.expect(sche.manuAbor(iozz, "virt")); try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "virt", "t").code); const second = sche.manuRing(iozz, "virt").?; defer second.rele(); try tszz.expect(first != second); const more = [_][]const u8{ "s1", "s2", "s3", "s4", "s5", "s6", "s7", "s8" }; for (more) |step| try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, step, "t").code); try tszz.expect(sche.manuRing(iozz, "virt") == null); const last = sche.manuRing(iozz, "s8").?; last.rele(); }
test "manuLive and manuPaus: live only while the step's ring is not sealed; a stale registry entry is never touched" { var impl = std.Io.Threaded.init(tszz.allocator, .{}); defer impl.deinit(); const iozz = impl.io(); var list = tasks(); var sche: Sche = .{}; try initz(&sche, list[0..]); defer sche.dein(); defer drain(&sche, iozz); try tszz.expect(!sche.manuLive(iozz, "virt")); try tszz.expectEqual(Sche.PausCode.none, sche.manuPaus(iozz, "virt", true)); try tszz.expectEqual(Sche.ManuCode.okzz, sche.manuRun(iozz, "virt", "t").code); try tszz.expect(sche.manuLive(iozz, "virt")); try tszz.expectEqual(Sche.PausCode.none, sche.manuPaus(iozz, "virt", true)); try tszz.expect(sche.manuAbor(iozz, "virt")); try tszz.expect(!sche.manuLive(iozz, "virt")); try tszz.expectEqual(Sche.PausCode.none, sche.manuPaus(iozz, "virt", false)); try tszz.expect(!sche.manuAbor(iozz, "virt")); }
